H.background();
const F = P.F, dt = P.dt, m = 2;
const J = F * dt;
const dv = J / m;
H.text("Impulse-Momentum Theorem:  J = F*dt = dp", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Constant force F over time dt gives impulse J = change in momentum dp", 24, 52, { color: H.colors.sub, size: 13 });
const v = H.plot2d({ xMin: 0, xMax: 5, yMin: 0, yMax: 12, box: { x: 70, y: 90, w: 360, h: 300 } });
v.grid(); v.axes();
v.line(0, F, dt, F, { color: H.colors.accent, width: 3 });
v.line(dt, 0, dt, F, { color: H.colors.accent, width: 1, dash: [4, 4] });
const sweep = dt * (0.5 + 0.5 * Math.sin(t * 0.8));
v.path([[0, 0], [0, F], [sweep, F], [sweep, 0]], { color: H.colors.accent2, fill: H.colors.accent2, close: true });
v.text("F = " + F.toFixed(1) + " N", dt * 0.4, F + 1, { color: H.colors.ink, size: 12 });
v.text("t (s)", 4.4, 0.6, { color: H.colors.sub, size: 12 });
v.text("F (N)", 0.2, 11.4, { color: H.colors.sub, size: 12 });
const px0 = 500, py = 230, track = 360;
H.line(px0, py + 30, px0 + track, py + 30, { color: H.colors.grid, width: 2 });
const period = 4;
const ph = (t % period) / period;
const v_now = dv * ph;
const x_now = px0 + 0.5 * (track * 0.6) * ph * ph + 20;
H.rect(x_now, py, 44, 30, { fill: H.colors.violet, stroke: H.colors.ink, width: 2, radius: 4 });
H.arrow(x_now + 44, py + 15, x_now + 44 + Math.min(60, 8 + v_now * 6), py + 15, { color: H.colors.warn, width: 3 });
H.text("cart  m = " + m.toFixed(0) + " kg", px0, py - 24, { color: H.colors.sub, size: 13 });
H.text("J = F*dt = " + J.toFixed(2) + " N*s", px0, py + 80, { color: H.colors.accent, size: 14, weight: 700 });
H.text("dp = J  =>  dv = J/m = " + dv.toFixed(2) + " m/s", px0, py + 102, { color: H.colors.good, size: 13 });
H.text("v(now) = " + v_now.toFixed(2) + " m/s", px0, py + 124, { color: H.colors.violet, size: 13 });
